<script setup>
import {computed,onMounted,ref} from 'vue';import axios from 'axios';import {useRoute,useRouter} from 'vue-router';import {trackMobileNavigation,backInMobile} from './mobileNavigation.js';import {FilePenLine,RefreshCw,ChevronRight} from '@lucide/vue';
const route=useRoute(),router=useRouter();trackMobileNavigation(router);
const selected=computed(()=>items.value.find(item=>String(item.id || item.serverId)===String(route.query.workId || '')) || null);
function openItem(item){router.push({path:'/mobile/workspace',query:{view:'mywork',workId:String(item.id || item.serverId)}});}
function back(){backInMobile(router,{path:'/mobile/workspace',query:{view:'mywork'}});}
const props=defineProps({apiBase:String,sessionToken:String});const emit=defineEmits(['draft','tasks']);
const items=ref([]),loading=ref(false),error=ref(''),clinicalAvailable=ref(true);
async function load(){loading.value=true;error.value='';try{const {data}=await axios.get(`${props.apiBase}/my-work`,{headers:{'X-Quick-View-Session':props.sessionToken},withCredentials:true});items.value=data.items || [];clinicalAvailable.value=data.clinicalAvailable!==false;}catch(e){error.value=e.response?.data?.error?.message || 'Could not load your work.';}finally{loading.value=false;}}
const status=item=>String(item.status || 'not_started').replaceAll('_',' ');
const title=item=>item.clientName || item.client_name || item.initials || item.title || item.action || 'Documentation item';
const dos=item=>String(item.date || item.dos || item.dateOfService || item.serviceDate || item.dosDate || '').slice(0,10);
onMounted(load);
</script>
<template><section class="mobile-mywork"><header><h2>Documentation queue</h2><button aria-label="Refresh My Work" @click="load"><RefreshCw :size="17"/></button></header><p>Your documentation queue for this workspace.</p><p v-if="loading" role="status">Loading your work…</p><p v-if="error" role="alert">{{ error }} <button @click="load">Try again</button></p><button v-for="item in items" :key="item.id || item.serverId" class="work-row" @click="openItem(item)"><FilePenLine :size="21"/><span><strong>{{ title(item) }}</strong><small>{{ dos(item) }}<template v-if="item.noteType || item.toolId"> · {{ item.noteType || item.toolId }}</template></small></span><span class="status">{{ status(item) }}</span><ChevronRight :size="17"/></button><p v-if="!loading && !error && !items.length">{{ clinicalAvailable?'Your documentation queue is clear.':'Clinical documentation is not available for this account.' }}</p><button class="task-link" @click="emit('tasks')">View my tasks <ChevronRight :size="15"/></button><section v-if="selected" class="work-detail"><button @click="back">← Back</button><h3>{{ title(selected) }}</h3><p>{{ dos(selected) }} · {{ status(selected) }}</p><p>{{ selected.action || selected.todo || selected.description }}</p><p>Use Note Workspace to prepare a draft. Final chart attachment and signing stay in the full clinical workspace.</p><button @click="emit('draft',selected)">Prepare draft in Note Workspace</button></section></section></template>
<style scoped>.mobile-mywork{background:#fff;padding:18px;color:#1b385d;min-width:0}.mobile-mywork>header{display:flex;align-items:center;justify-content:space-between}.mobile-mywork h2{font-size:19px}.mobile-mywork p{font-size:13px;color:#657d9c;line-height:1.6}.mobile-mywork button{font:inherit;cursor:pointer;color:inherit}.mobile-mywork header button{border:0;background:#f1f5fb;border-radius:8px;padding:9px}.work-row{display:flex;width:100%;align-items:center;gap:10px;text-align:left;background:white;border:0;border-bottom:1px solid #e5ebf5;padding:17px 0}.work-row>span:first-of-type{flex:1;min-width:0;display:flex;flex-direction:column;gap:5px}.work-row strong{font-size:13px}.work-row small{font-size:11px;color:#7b8ca6}.status{font-size:10px;background:#edf4ff;color:#2757a4;padding:4px 7px;border-radius:7px;text-transform:capitalize}.task-link,.work-detail button{display:flex;gap:5px;align-items:center;background:#edf3ff;border:1px solid #d8e3f6;border-radius:9px;padding:10px 14px;margin:14px 0}.work-detail{border-top:1px solid #dbe4f3;margin-top:20px;padding-top:12px}.work-detail h3{font-size:16px}</style>
